// Ground-truth AES-128/192/256 ECB single-block encrypt, from-scratch (harness only, /tmp).
const SBOX = new Uint8Array(256);
const RCON = [0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36,0x6c,0xd8,0xab,0x4d];
(function build() {
  // multiplicative inverse via log/antilog over GF(2^8) with generator 3
  const p = new Uint8Array(256), l = new Uint8Array(256);
  let x = 1;
  for (let i = 0; i < 255; i++) { p[i] = x; l[x] = i; x ^= (x << 1) ^ ((x & 0x80) ? 0x11b : 0); x &= 0xff; }
  const inv = (a) => (a === 0 ? 0 : p[255 - l[a]]);
  for (let i = 0; i < 256; i++) {
    const b = inv(i);
    let s = b;
    for (let k = 0; k < 4; k++) s ^= ((b << (k + 1)) | (b >>> (7 - k))) & 0xff;
    SBOX[i] = s ^ 0x63;
  }
})();
const xt = (a) => ((a << 1) ^ ((a & 0x80) ? 0x1b : 0)) & 0xff;
const m = (a, b) => { let r = 0; while (b) { if (b & 1) r ^= a; a = xt(a); b >>= 1; } return r & 0xff; };

export function expandKey(key) {
  const nk = key.length / 4, nr = nk + 6;
  const w = [];
  for (let i = 0; i < nk; i++) w.push([key[4*i], key[4*i+1], key[4*i+2], key[4*i+3]]);
  for (let i = nk; i < 4 * (nr + 1); i++) {
    let t = w[i - 1].slice();
    if (i % nk === 0) {
      t.push(t.shift());
      t = t.map((v) => SBOX[v]);
      t[0] ^= RCON[i / nk - 1];
    } else if (nk > 6 && i % nk === 4) {
      t = t.map((v) => SBOX[v]);
    }
    w.push(w[i - nk].map((v, j) => v ^ t[j]));
  }
  return { w, nr };
}

export function encryptBlock(key, block) {
  const { w, nr } = expandKey(key);
  let s = Array.from(block);
  const ark = (r) => { for (let i = 0; i < 16; i++) s[i] ^= w[r * 4 + ((i / 4) | 0)][i % 4]; };
  ark(0);
  for (let r = 1; r <= nr; r++) {
    s = s.map((v) => SBOX[v]);
    // ShiftRows on column-major (state[col*4+row])
    const t = s.slice();
    for (let c = 0; c < 4; c++) for (let row = 0; row < 4; row++) s[c * 4 + row] = t[((c + row) % 4) * 4 + row];
    if (r !== nr) {
      const u = s.slice();
      for (let c = 0; c < 4; c++) {
        const a0=u[c*4],a1=u[c*4+1],a2=u[c*4+2],a3=u[c*4+3];
        s[c*4]   = m(a0,2)^m(a1,3)^a2^a3;
        s[c*4+1] = a0^m(a1,2)^m(a2,3)^a3;
        s[c*4+2] = a0^a1^m(a2,2)^m(a3,3);
        s[c*4+3] = m(a0,3)^a1^a2^m(a3,2);
      }
    }
    ark(r);
  }
  return Uint8Array.from(s);
}

// Sanity check ground-truth AES against the reference executable output for one known case.
import { encryptBlock } from './aes.mjs';
const key = Buffer.from('0123456789abcdef', 'utf8');
const blk = Buffer.from('0123456789abcdef', 'utf8');
const ct = encryptBlock(key, blk);
console.log([...ct].map((b) => b.toString(16).padStart(2, '0')).join(' '));
